test('invoiceTotals with 21% VAT and discount produces correct total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 * 5 = 47500
  // Discount: 47500 * 5 / 100 = 2375
  // Discounted: 47500 - 2375 = 45125
  // VAT: 45125 * 21 / 100 = 9476.25, rounded to 9476
  // Total: 47500 - 2375 + 9476 = 54601
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

